SELECT web_site_id, web_manager, d_year, d_month_seq, month_sales, prev_month_sales, CASE WHEN prev_month_sales IS NULL THEN 'N/A' WHEN month_sales > prev_month_sales THEN 'Increase' WHEN month_sales < prev_month_sales THEN 'Decrease' ELSE 'Flat' END AS sales_trend, CASE WHEN month_sales >= 50000 THEN 'High' WHEN month_sales BETWEEN 20000 AND 49999.99 THEN 'Medium' ELSE 'Low' END AS sales_category, CASE WHEN has_good_credit = 1 THEN 'Good Credit Present' ELSE 'No Good Credit' END AS credit_presence FROM ( SELECT web_site_id, web_manager, d_year, d_month_seq, month_sales, has_good_credit, LAG(month_sales) OVER (PARTITION BY web_site_id ORDER BY d_year, d_month_seq) AS prev_month_sales FROM ( SELECT ws_site.web_site_id, ws_site.web_manager, d_sold.d_year, d_sold.d_month_seq, SUM(ws.ws_net_paid_inc_tax) AS month_sales, MAX(CASE WHEN cd.cd_credit_rating IN ('A','B') THEN 1 ELSE 0 END) AS has_good_credit FROM web_sales ws JOIN date_dim d_sold ON ws.ws_sold_date_sk = d_sold.d_date_sk JOIN web_site ws_site ON ws.ws_web_site_sk = ws_site.web_site_sk JOIN customer_demographics cd ON ws.ws_bill_cdemo_sk = cd.cd_demo_sk GROUP BY ws_site.web_site_id, ws_site.web_manager, d_sold.d_year, d_sold.d_month_seq ) monthly ) final ORDER BY web_site_id, d_year, d_month_seq
